import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.*

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val input = mutableListOf<String>()
    var line: String?
    while (reader.readLine().also { line = it } != null) {
        input.add(line!!)
    }

    val parts = input[0].split(" ").map { it.toInt() }
    val n = parts[0]
    val m = parts[1]

    if (n > m) {
        println(n - m)
        return
    }

    val data = mutableMapOf<Int, Int>()
    data[n] = n

    var find = 0
    while (true) {
        val map = mutableMapOf<Int, Int>()
        for (i in data.keys) {
            val x = i
            if (x - 1 >= 1) {
                map[x - 1] = x - 1
                if (x - 1 == m) {
                    println(find + 1)
                    return
                }
            }
            if (x * 2 <= m * 1.5) {
                map[x * 2] = x * 2
                if (x * 2 == m) {
                    println(find + 1)
                    return
                }
            }
        }
        data.clear()
        data.putAll(map)
        find += 1
    }
}
